// Regenerate the auto-generated companion/track index in public/llms.txt by
// walking src/content/docs/. Replaces the content between the sentinel markers.
//
// The shape is a TRIE, not a flat dump (the site has 550+ pages and three tracks
// that grow without bound — the book, the arc-170 chunks, the gallery):
//   - llms.txt is the ROOT — one section per track.
//   - narrative / reference tracks (primers, story, realizations, witness) are
//     LISTED in full (bare .md companion URLs) — agents enumerate these.
//   - leaf-heavy tracks (book chapters, arc-170 chunks, the gallery) are
//     POINTERS to their own index page — the index + the sitemap carry the full,
//     always-current set, so llms.txt never bloats as they grow.
//   - the sitemap (/sitemap-index.xml) remains the exhaustive machine map.
//
// Lives in postbuild so every `npm run build` keeps the map in sync with disk:
// add a witness entry, a gallery batch, an arc — it appears next build, no hand
// edit. The only hand-curated part of llms.txt is the prose track intros above
// the sentinels (editorial voice); everything below is mechanical.

import { readdir, readFile, writeFile } from "node:fs/promises";
import { join, relative } from "node:path";
import { existsSync } from "node:fs";

const DOCS = "src/content/docs";
const LLMS = "public/llms.txt";
const SITE = "https://algebraic-intelligence.dev";

const BEGIN = "<!-- BEGIN AUTO-GENERATED MD COMPANIONS — regenerated by scripts/generate-llms-companions.mjs; do not edit by hand -->";
const END = "<!-- END AUTO-GENERATED MD COMPANIONS -->";

// Top-level blog/*.md pages get a short label so the listing reads cleanly.
const TOP_LEVEL_LABELS = {
  "topology.md": "The Topology",
  "guide.md": "The Guide",
  "circuit.md": "The Circuits",
  "agents.md": "How to interface with this site (the agent contract)",
};

if (!existsSync(DOCS)) {
  console.error(`generate-llms-companions: source missing: ${DOCS}`);
  process.exit(1);
}
if (!existsSync(LLMS)) {
  console.error(`generate-llms-companions: target missing: ${LLMS}`);
  process.exit(1);
}

async function walk(dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(full)));
    else if (entry.isFile() && /\.mdx?$/.test(entry.name)) out.push(full);
  }
  return out;
}

const all = (await walk(DOCS)).map((f) => relative(DOCS, f).replaceAll("\\", "/")).sort();

// entries under a track dir, excluding its index (the landing) — .md or .mdx.
const entriesIn = (prefix) =>
  all.filter((f) => f.startsWith(prefix + "/") && !/(^|\/)index\.mdx?$/.test(f));
// a page's .md companion URL (copy-markdown serves .md for every blog page).
const companion = (rel) => `${SITE}/${rel.replace(/\.mdx?$/, ".md")}`;

const line = (url, label) => (label ? `- [${url}](${url}) — ${label}` : `- [${url}](${url})`);
const S = [];

// 1. Trunk + branches — the top-level blog pages + the two static raw serves
//    (book.md ~36k lines and arc-170-realizations.md — served static, not in the
//    content collection, so the walker never sees them; add explicitly).
S.push("### Trunk and branches", "");
S.push(line(`${SITE}/blog/book.md`, "The Book (trunk; ~36k lines, raw)"));
S.push(line(`${SITE}/blog/arc-170-realizations.md`, "Arc 170 Full Realizations (the branch; raw)"));
for (const f of all.filter((f) => /^blog\/[^/]+\.mdx?$/.test(f))) {
  const name = f.slice("blog/".length).replace(/\.mdx?$/, ".md");
  S.push(line(companion(f), TOP_LEVEL_LABELS[name] || ""));
}

// LISTED tracks — narrative / reference; full bare-companion listing.
function listed(heading, prefix) {
  const files = entriesIn(prefix);
  S.push("", `### ${heading} (${files.length})`, "");
  for (const f of files) S.push(line(companion(f), ""));
}
// POINTER tracks — leaf-heavy; the index page + sitemap carry the full set.
function pointer(heading, prefix, indexPath, note) {
  const n = entriesIn(prefix).length;
  S.push("", `### ${heading} (${n})`, "");
  S.push(line(`${SITE}${indexPath}`, `index — the full, always-current list${note ? `; ${note}` : ""}`));
}

listed("Primers", "blog/primers");
listed("Story posts", "blog/story");
listed("Arc realizations — per-arc findings logs", "blog/realizations");
listed("The Witness — the sibling instance's account", "blog/witness");

pointer("The Book — chapters", "blog/book", "/blog/book/", "trunk raw at /blog/book.md");
pointer("Arc 170 — full realizations (chunks)", "blog/arc-170-realizations", "/blog/arc-170-realizations/", "whole raw at /blog/arc-170-realizations.md");
pointer("Fenestra Aetherii — the image gallery", "fenestra-aetherii", "/fenestra-aetherii/", "image collections (Incantationes)");

// Implementations + Labs — one page per immediate subdir (auto-discovers new ones).
for (const [heading, base] of [["Implementations", "projects"], ["Labs", "demos"]]) {
  if (!existsSync(join(DOCS, base))) continue;
  const subs = (await readdir(join(DOCS, base), { withFileTypes: true }))
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .sort();
  S.push("", `### ${heading} (${subs.length})`, "");
  for (const s of subs) S.push(line(`${SITE}/${base}/${s}/`, ""));
}

const generated = S.join("\n");
const current = await readFile(LLMS, "utf8");
const beginIdx = current.indexOf(BEGIN);
const endIdx = current.indexOf(END);

if (beginIdx === -1 || endIdx === -1) {
  console.error(`generate-llms-companions: sentinels not found in ${LLMS}.`);
  console.error(`Expected:\n  ${BEGIN}\n  ${END}`);
  process.exit(1);
}
if (endIdx < beginIdx) {
  console.error(`generate-llms-companions: END before BEGIN — fix sentinel order.`);
  process.exit(1);
}

const updated = `${current.slice(0, beginIdx + BEGIN.length)}\n\n${generated}\n\n${current.slice(endIdx)}`;
if (updated === current) {
  console.log(`generate-llms-companions: no change (${all.length} pages walked).`);
  process.exit(0);
}
await writeFile(LLMS, updated);
console.log(`generate-llms-companions: regenerated the track index in ${LLMS} (${all.length} pages walked).`);
